package com.argument.exporttrial;

import com.argument.common.exception.*;
import com.argument.common.response.*;
import com.argument.adjudication.AdjudicationController;
import com.argument.version.VersionJson;
import com.argument.version.port.*;
import com.argument.finalreview.FinalReviewRepository;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.springframework.context.annotation.Profile;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import static com.argument.adjudication.AdjudicationService.require;

@RestController @Profile("(local | test) & !prod") @RequestMapping("/api/v1")
public class ExportTrialController {
    private final ExportTrialService service;private final VersionIdentity identity;private final AnnotationDependencies data;private final FinalReviewRepository finals;private final ObjectMapper mapper;private final TrialUploadService uploads;
    public ExportTrialController(ExportTrialService service,VersionIdentity identity,AnnotationDependencies data,FinalReviewRepository finals,ObjectMapper mapper,TrialUploadService uploads){this.service=service;this.identity=identity;this.data=data;this.finals=finals;this.mapper=mapper;this.uploads=uploads;}
    @PostMapping(value="/file-assets",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public ApiResponse<ObjectNode> upload(@RequestHeader(value="Authorization",required=false)String auth,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestPart("file")MultipartFile file,@RequestPart("metadata")ObjectNode metadata)throws java.io.IOException{var actor=identity.authenticate(auth);require(file.getSize()<=20_000_000,ErrorCode.FILE_INVALID,"文件超过上传限额");String request=VersionJson.uuid();return ApiResponse.okWithRequestId(uploads.upload(actor,key,metadata,file.getBytes(),request),request);}
    @GetMapping("/exports/eligible-final-versions")
    public ApiResponse<ObjectNode> eligible(@RequestHeader(value="Authorization",required=false)String auth,@RequestParam Map<String,String> query){
        var actor=identity.authenticate(auth);service.role(actor,"EXPORT_CREATE");only(query,Set.of("guideVersionId","sourceType","page","size"));if(query.containsKey("guideVersionId"))VersionJson.uuid(query.get("guideVersionId"));if(query.containsKey("sourceType"))require(Set.of("ORDINARY_JUDGMENT","GUIDING_CASE","REFERENCE_CASE").contains(query.get("sourceType")),ErrorCode.VALIDATION_ERROR,"无效文书来源");var all=new ArrayList<ObjectNode>();
        for(var task:data.find("task",null,null)){if(!actor.role("ADMIN")&&!actor.id().equals(task.path("ownerUserId").asText()))continue;for(var doc:data.find("taskDocument","taskId",task.path("id").asText()))for(var v:finals.versions(doc.path("id").asText())){if(!"IN_DATABASE".equals(v.path("status").asText()))continue;if(query.containsKey("guideVersionId")&&!query.get("guideVersionId").equals(v.path("guideVersionId").asText()))continue;var document=data.read("document",doc.path("documentId").asText());if(query.containsKey("sourceType")&&!query.get("sourceType").equals(document.path("sourceType").asText()))continue;var snapshot=finals.snapshot(v.path("id").asText());var item=mapper.createObjectNode();for(String f:List.of("id","versionNumber","guideVersionId","status"))item.set(f,v.get(f));item.set("finalVersion",v);item.set("title",document.get("title"));item.set("caseNumber",document.path("caseNumber"));item.set("sourceType",document.get("sourceType"));item.put("guideVersionCode",data.read("guideVersion",v.path("guideVersionId").asText()).path("versionCode").asText()).put("elementCount",snapshot.path("elements").size()).put("relationCount",snapshot.path("relations").size());var preview=item.putArray("preview");for(var e:snapshot.path("elements")){if(preview.size()>=5)break;preview.addObject().set("id",e.path("id"));var p=(ObjectNode)preview.get(preview.size()-1);for(String f:List.of("displayNo","text","startOffset","endOffset","labelCode"))p.set(f,e.path(f));p.set("type",e.path("labelCode"));}var safeDocument=item.putObject("document");for(String f:List.of("id","title","caseNumber","sourceType"))safeDocument.set(f,document.path(f));item.putObject("guideVersion").put("id",v.path("guideVersionId").asText()).put("versionCode",item.path("guideVersionCode").asText());item.set("previewElements",preview);item.remove(List.of("id","versionNumber","guideVersionId","status","title","caseNumber","sourceType","guideVersionCode","preview"));all.add(item);}}
        int page=page(query),size=size(query);var result=mapper.createObjectNode();var items=result.putArray("items");all.stream().sorted(Comparator.comparing(n->n.path("finalVersion").path("id").asText())).skip((long)(page-1)*size).limit(size).forEach(items::add);return ApiResponse.ok(result,new PageMeta(page,size,all.size()));
    }
    @PostMapping("/exports") public ApiResponse<ObjectNode> create(@RequestHeader(value="Authorization",required=false)String auth,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody ObjectNode body){var actor=identity.authenticate(auth);fields(body,Set.of("finalVersionIds","format","include"));return ApiResponse.ok(service.create(actor,key,body));}
    @GetMapping("/exports") public ApiResponse<ObjectNode> list(@RequestHeader(value="Authorization",required=false)String auth,@RequestParam Map<String,String> q){var actor=identity.authenticate(auth);only(q,Set.of("status","format","page","size","sort"));require(!q.containsKey("sort")||"requestedAt:desc".equals(q.get("sort")),ErrorCode.VALIDATION_ERROR,"不支持的排序");int page=page(q),size=size(q);var result=service.list(actor,q.get("status"),q.get("format"),page,size);return ApiResponse.ok(result,new PageMeta(page,size,result.path("total").asLong()));}
    @GetMapping("/exports/{id}") public ApiResponse<ObjectNode> read(@RequestHeader(value="Authorization",required=false)String auth,@PathVariable String id){return ApiResponse.ok(service.read(identity.authenticate(auth),id));}
    @PostMapping("/exports/{id}/download-tickets") public ApiResponse<ObjectNode> ticket(@RequestHeader(value="Authorization",required=false)String auth,@PathVariable String id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody ObjectNode body){return ticket(auth,id,key,body,false);}
    @PostMapping("/file-assets/{id}/download-tickets") public ApiResponse<ObjectNode> fileTicket(@RequestHeader(value="Authorization",required=false)String auth,@PathVariable String id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody ObjectNode body){return ticket(auth,id,key,body,true);}
    private ApiResponse<ObjectNode> ticket(String auth,String id,String key,ObjectNode body,boolean file){var actor=identity.authenticate(auth);fields(body,Set.of("purpose"));require(body.path("purpose").isTextual(),ErrorCode.VALIDATION_ERROR,"下载目的必须是文本");String request=VersionJson.uuid();return ApiResponse.okWithRequestId(service.ticket(actor,id,file,key,body,request),request);}
    @GetMapping("/file-assets/{id}/content") public ResponseEntity<byte[]> content(@RequestHeader(value="Authorization",required=false)String auth,@PathVariable String id,@RequestParam Map<String,String> q){only(q,Set.of("downloadToken"));var file=service.content(identity.authenticate(auth),id,q.get("downloadToken"));return ResponseEntity.ok().contentType(MediaType.parseMediaType(file.mimeType())).contentLength(file.bytes().length).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(file.name(),StandardCharsets.UTF_8).build().toString()).header(HttpHeaders.CACHE_CONTROL,"no-store").header("X-Content-Type-Options","nosniff").body(file.bytes());}
    private static void fields(ObjectNode n,Set<String> allowed){var fields=new HashSet<String>();n.fieldNames().forEachRemaining(fields::add);require(fields.equals(allowed),ErrorCode.VALIDATION_ERROR,"请求字段不符合试行契约");}
    private static void only(Map<String,String> q,Set<String> allowed){require(allowed.containsAll(q.keySet()),ErrorCode.VALIDATION_ERROR,"不支持的查询字段");}
    private static int page(Map<String,String> q){return AdjudicationController.integer(q.getOrDefault("page","1"));}
    private static int size(Map<String,String> q){int size=AdjudicationController.integer(q.getOrDefault("size","20"));require(size<=100,ErrorCode.VALIDATION_ERROR,"每页最多 100 条");return size;}
}
